[package]
name = "observatory-cli"
description = "Headless replay and inspection of Droid sessions over observatory-core"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
publish.workspace = true

[[bin]]
name = "observatory-cli"
path = "src/main.rs"

[dependencies]
observatory-core.workspace = true
use std::process::ExitCode;

use observatory_core::config::Config;

fn main() -> ExitCode {
    if let Err(err) = Config::load(None) {
        eprintln!("observatory-cli: {err}");
        return ExitCode::FAILURE;
    }
    println!(
        "observatory-cli {}: no commands yet",
        env!("CARGO_PKG_VERSION")
    );
    ExitCode::SUCCESS
}
[package]
name = "observatory-core"
description = "Ingest, model, metrics, store and control for droid-observatory (synchronous, no UI)"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
publish.workspace = true

[features]
# Platform modules sit behind features so the UI crate can depend on core with
# default-features = false and still build for wasm32 (architecture I9).
default = ["store", "watch", "rpc", "github", "secrets"]
store = ["dep:rusqlite"]
watch = []
rpc = []
github = []
secrets = ["dep:keyring-core", "dep:apple-native-keyring-store"]

[dependencies]
serde.workspace = true
serde_json.workspace = true
toml.workspace = true
tracing.workspace = true
time.workspace = true
rusqlite = { workspace = true, optional = true }
keyring-core = { workspace = true, optional = true }

[target.'cfg(target_os = "macos")'.dependencies]
apple-native-keyring-store = { workspace = true, optional = true }

# Declared ahead of the modules that use them; each worker removes its entry when the
# first use lands (cargo machete reads this list).
[package.metadata.cargo-machete]
ignored = ["rusqlite", "keyring-core", "apple-native-keyring-store"]
//! Synchronous core of droid-observatory: no async runtime, no UI (architecture I1, I2).

pub mod config;
pub mod mapping;
pub mod model;
//! Raw record to canonical event mapping. Compiled to wasm for the UI (architecture I9).

mod version;

pub use version::MappingVersion;
use serde::{Deserialize, Serialize};

/// Version of the rules that turned a raw record into an `Event`. Stored on every event so
/// a change of rules is visible in old data.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum MappingVersion {
    V1,
}

impl MappingVersion {
    pub const LATEST: MappingVersion = MappingVersion::V1;
}
//! Configuration contract: `config/observatory.example.toml` is the source of every default.
//!
//! Compiled to wasm for the UI (architecture I9), so nothing here depends on the platform
//! beyond `std::fs` and `std::env`, which only run when the shell asks for a file.

use std::ffi::OsString;
use std::fmt;
use std::io;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

/// Environment variable that overrides the config file location.
pub const CONFIG_ENV: &str = "OBSERVATORY_CONFIG";

/// Location below `$HOME` of the user's config file.
const DEFAULT_RELATIVE_PATH: &str = ".droid-observatory/config.toml";

#[derive(Debug)]
pub enum ConfigError {
    Io {
        path: PathBuf,
        source: io::Error,
    },
    Parse {
        path: Option<PathBuf>,
        message: String,
    },
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io { path, source } => {
                write!(f, "cannot read config {}: {source}", path.display())
            }
            Self::Parse {
                path: Some(path),
                message,
            } => {
                write!(f, "invalid config {}: {message}", path.display())
            }
            Self::Parse {
                path: None,
                message,
            } => write!(f, "invalid config: {message}"),
        }
    }
}

impl std::error::Error for ConfigError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Io { source, .. } => Some(source),
            Self::Parse { .. } => None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum MergePolicy {
    /// Read the policy from GitHub rulesets and branch protection.
    Auto,
    /// Always show the Merge button.
    Human,
    /// Never show the Merge button.
    Policy,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum OverheadApportionment {
    Separate,
    Equal,
}

/// Every table accepts partial files: a missing key keeps its default.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
